1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 40px 16px;
12	    font: 16px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    background: #f5f5f4;
14	    color: #1c1917;
15	  }
16	  main { max-width: 520px; margin: 0 auto; }
17	  h1 { font-size: 28px; margin: 0 0 16px; }
18	  form { display: flex; gap: 8px; margin-bottom: 16px; }
19	  input[type="text"] {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 10px 12px;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 8px;
26	    background: #fff;
27	  }
28	  input[type="text"]:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }
29	  button {
30	    font: inherit;
31	    border: 0;
32	    border-radius: 8px;
33	    cursor: pointer;
34	  }
35	  .add { padding: 10px 18px; background: #2563eb; color: #fff; }
36	  .add:hover { background: #1d4ed8; }
37	  ul { list-style: none; margin: 0; padding: 0; }
38	  li {
39	    display: flex;
40	    align-items: center;
41	    gap: 12px;
42	    padding: 10px 12px;
43	    margin-bottom: 8px;
44	    background: #fff;
45	    border: 1px solid #e7e5e4;
46	    border-radius: 8px;
47	  }
48	  .text { flex: 1; overflow-wrap: anywhere; }
49	  li input[type="checkbox"] { width: 18px; height: 18px; margin: 0; cursor: pointer; accent-color: #2563eb; }
50	  li[data-completed="true"] .text { color: #a8a29e; text-decoration: line-through; }
51	  .filters { display: flex; gap: 8px; margin-bottom: 16px; }
52	  .filters button { padding: 6px 12px; background: transparent; color: #44403c; border: 1px solid #d6d3d1; }
53	  .filters button:hover { background: #e7e5e4; }
54	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
55	  .delete { padding: 6px 10px; background: transparent; color: #b91c1c; }
56	  .delete:hover { background: #fee2e2; }
57	  .empty { color: #78716c; text-align: center; padding: 16px 0; }
58	</style>
59	</head>
60	<body>
61	<main>
62	  <h1>Todos</h1>
63	  <form id="todo-form">
64	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
65	    <button type="submit" class="add" data-testid="todo-add">Add</button>
66	  </form>
67	  <div class="filters" role="group" aria-label="Filter todos">
68	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
69	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
70	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
71	  </div>
72	  <ul data-testid="todo-list"></ul>
73	  <p class="empty" hidden>No todos yet.</p>
74	</main>
75	<script>
76	(function () {
77	  var STORAGE_KEY = 'todos';
78	  var form = document.getElementById('todo-form');
79	  var input = document.querySelector('[data-testid="todo-input"]');
80	  var list = document.querySelector('[data-testid="todo-list"]');
81	  var empty = document.querySelector('.empty');
82	  var filterButtons = document.querySelectorAll('[data-filter]');
83	
84	  function load() {
85	    try {
86	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
87	      return Array.isArray(data) ? data : [];
88	    } catch (e) {
89	      return [];
90	    }
91	  }
92	
93	  function save() {
94	    try {
95	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
96	    } catch (e) {
97	      // Storage may be unavailable (e.g. blocked); the app still works in memory.
98	    }
99	  }
100	
101	  function makeId() {
102	    if (window.crypto && typeof crypto.randomUUID === 'function') {
103	      return crypto.randomUUID();
104	    }
105	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
106	  }
107	
108	  var todos = load();
109	  var filter = 'all';
110	
111	  // Ordering rule (project decision): active todos first, completed todos below.
112	  // Within each group, keep insertion order (oldest first). `todos` is stored
113	  // in insertion order, so splitting it into two groups preserves that.
114	  function visibleTodos() {
115	    var active = todos.filter(function (t) { return !t.completed; });
116	    var completed = todos.filter(function (t) { return t.completed; });
117	    if (filter === 'active') return active;
118	    if (filter === 'completed') return completed;
119	    return active.concat(completed);
120	  }
121	
122	  function render() {
123	    list.textContent = '';
124	    var visible = visibleTodos();
125	    visible.forEach(function (todo) {
126	      var li = document.createElement('li');
127	      li.setAttribute('data-testid', 'todo-item');
128	      li.setAttribute('data-id', todo.id);
129	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
130	
131	      var toggle = document.createElement('input');
132	      toggle.type = 'checkbox';
133	      toggle.checked = !!todo.completed;
134	      toggle.setAttribute('data-testid', 'todo-toggle');
135	      toggle.setAttribute('aria-label', 'Mark complete');
136	      toggle.addEventListener('change', function () { setCompleted(todo.id, toggle.checked); });
137	
138	      var text = document.createElement('span');
139	      text.className = 'text';
140	      text.setAttribute('data-testid', 'todo-text');
141	      text.textContent = todo.text;
142	
143	      var del = document.createElement('button');
144	      del.type = 'button';
145	      del.className = 'delete';
146	      del.setAttribute('data-testid', 'todo-delete');
147	      del.setAttribute('aria-label', 'Delete todo');
148	      del.textContent = 'Delete';
149	      del.addEventListener('click', function () { remove(todo.id); });
150	
151	      li.appendChild(toggle);
152	      li.appendChild(text);
153	      li.appendChild(del);
154	      list.appendChild(li);
155	    });
156	    empty.textContent = todos.length === 0 ? 'No todos yet.'
157	      : filter === 'active' ? 'No active todos.'
158	      : 'No completed todos.';
159	    empty.hidden = visible.length > 0;
160	    filterButtons.forEach(function (btn) {
161	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
162	    });
163	  }
164	
165	  function add(text) {
166	    todos.push({ id: makeId(), text: text, completed: false, createdAt: Date.now() });
167	    save();
168	    render();
169	  }
170	
171	  function remove(id) {
172	    todos = todos.filter(function (t) { return t.id !== id; });
173	    save();
174	    render();
175	  }
176	
177	  function setCompleted(id, completed) {
178	    todos.forEach(function (t) { if (t.id === id) t.completed = completed; });
179	    save();
180	    render();
181	  }
182	
183	  filterButtons.forEach(function (btn) {
184	    btn.addEventListener('click', function () {
185	      filter = btn.getAttribute('data-filter');
186	      render();
187	    });
188	  });
189	
190	  form.addEventListener('submit', function (e) {
191	    e.preventDefault();
192	    var text = input.value.trim();
193	    if (!text) return;
194	    add(text);
195	    input.value = '';
196	    input.focus();
197	  });
198	
199	  render();
200	})();
201	</script>
202	</body>
203	</html>
