p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)

rep('''  input[type="text"]:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }''',
'''  input[type="date"] {
    padding: 10px 12px;
    font: inherit;
    border: 1px solid #d6d3d1;
    border-radius: 8px;
    background: #fff;
    color: inherit;
  }
  input[type="text"]:focus, input[type="date"]:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }''')
rep('''  form { display: flex; gap: 8px; margin-bottom: 16px; }''',
'''  form { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }''')
rep('''  li[data-completed="true"] .text { color: #a8a29e; text-decoration: line-through; }''',
'''  li[data-completed="true"] .text { color: #a8a29e; text-decoration: line-through; }
  .due { font-size: 14px; color: #57534e; white-space: nowrap; }
  li[data-overdue="true"] { border-color: #fca5a5; box-shadow: inset 3px 0 0 #dc2626; }
  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }''')
rep('''    <button type="submit" class="add" data-testid="todo-add">Add</button>''',
'''    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
    <button type="submit" class="add" data-testid="todo-add">Add</button>''')
rep('''  var input = document.querySelector('[data-testid="todo-input"]');''',
'''  var input = document.querySelector('[data-testid="todo-input"]');
  var dueInput = document.querySelector('[data-testid="todo-due"]');''')
rep('''  var todos = load();''',
'''  // Date rule (project decision): a due date is a plain "YYYY-MM-DD" string
  // meaning a LOCAL calendar date. Never pass it through Date parsing or UTC
  // (new Date("YYYY-MM-DD") is UTC midnight). Compare as strings, date-only.
  var DATE_RE = /^\\d{4}-\\d{2}-\\d{2}$/;

  function pad(n) { return (n < 10 ? '0' : '') + n; }

  function todayLocal() {
    var d = new Date();
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  }

  // Overdue: due date strictly before today's local date. Due today is never overdue.
  // Zero-padded YYYY-MM-DD strings sort the same as the dates they name.
  function isOverdue(todo, today) {
    return !!todo.due && todo.due < today;
  }

  function formatDue(due) {
    var parts = due.split('-');
    var local = new Date(+parts[0], +parts[1] - 1, +parts[2]);
    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
  }

  var todos = load();''')
rep('''    var visible = visibleTodos();
''','''    var visible = visibleTodos();
    var today = todayLocal();
    renderedDay = today;
''')
rep('''      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
''','''      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
''')
rep('''      li.appendChild(text);
''','''      li.appendChild(text);
      if (todo.due) {
        var due = document.createElement('time');
        due.className = 'due';
        due.setAttribute('data-testid', 'todo-due-date');
        due.setAttribute('datetime', todo.due);
        due.textContent = 'Due ' + formatDue(todo.due);
        li.appendChild(due);
      }
''')
rep('''  function add(text) {
    todos.push({ id: makeId(), text: text, completed: false, createdAt: Date.now() });''',
'''  function add(text, due) {
    todos.push({ id: makeId(), text: text, completed: false, createdAt: Date.now(), due: due });''')
rep('''    add(text);
    input.value = '';''',
'''    var due = DATE_RE.test(dueInput.value) ? dueInput.value : null;
    add(text, due);
    input.value = '';
    dueInput.value = '';''')
rep('''  var filter = 'all';
''','''  var filter = 'all';
  var renderedDay = null;
''')
rep('''  render();
})();''','''  render();

  // Overdue status changes at local midnight; re-render when the day rolls over.
  setInterval(function () {
    if (todayLocal() !== renderedDay) render();
  }, 30000);
})();''')
open(p,'w').write(s)
EOF
