const { chromium } = require('playwright');
const fs=require('fs');
const exe = ['chromium-1243','chromium-1234'].map(d=>process.env.HOME+'/Library/Caches/ms-playwright/'+d).find(fs.existsSync);
const url='file:///Users/vmysla/src/product-tracebility-ab-testing/ab-study/arms/todo-rep-control-01/control/index.html';
(async()=>{
  let bin; for (const d of fs.readdirSync(exe)) { const p=exe+'/'+d+'/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing'; if(fs.existsSync(p)) bin=p; }
  const browser = await chromium.launch({executablePath: bin});
  // [timezone, local time string, today]
  const cases=[['Pacific/Kiritimati','2026-09-13T00:30:00+14:00','2026-09-13'],
               ['America/Los_Angeles','2026-09-13T23:30:00-07:00','2026-09-13'],
               ['Pacific/Pago_Pago','2026-09-13T23:59:00-11:00','2026-09-13']];
  for (const [tz,t] of cases) {
    const ctx = await browser.newContext({timezoneId: tz});
    const page = await ctx.newPage();
    await page.clock.install({time: new Date(t)});
    await page.goto(url);
    for (const [txt,due] of [['yesterday','2026-09-12'],['today','2026-09-13'],['tomorrow','2026-09-14'],['none','']]) {
      await page.fill('[data-testid=todo-input]', txt);
      if (due) await page.fill('[data-testid=todo-due]', due);
      await page.click('[data-testid=todo-add]');
    }
    const rows = await page.$$eval('[data-testid=todo-item]', els=>els.map(e=>[e.querySelector('.text').textContent, e.dataset.overdue, e.querySelector('time')?.textContent||'-']));
    const stored = await page.evaluate(()=>localStorage.getItem('todos'));
    console.log(tz, JSON.stringify(rows), JSON.parse(stored).map(x=>x.due));
    if (tz==='America/Los_Angeles') {
      await page.clock.runFor(31*60*1000); // cross midnight
      console.log(' after midnight', JSON.stringify(await page.$$eval('[data-testid=todo-item]', els=>els.map(e=>[e.querySelector('.text').textContent, e.dataset.overdue]))));
      await page.screenshot({path:'shot.png'});
    }
    await ctx.close();
  }
  await browser.close();
})();
EOF
